def call_with_retries(send, max_attempts=4, base=0.5, cap=20.0, deadline_s=60.0):
    start = time.monotonic()
    for attempt in range(max_attempts):
        resp = send()
        if resp.ok:
            return resp
        if resp.status in (400, 401, 403, 404) or resp.is_quota_error:
            raise ApiError(resp)  # never retry
        wait = random.uniform(0, min(cap, base * 2 ** attempt))  # full jitter
        wait = max(wait, resp.retry_after_s or 0)  # Retry-After is a minimum
        if time.monotonic() - start + wait > deadline_s:
            break
        time.sleep(wait)
    raise GiveUp()
